from functools import lru_cache

def fib(n):
    @lru_cache(None)
    def f(i):
        if i <= 1:
            return i
        return f(i - 1) + f(i - 2)
    return f(n)

def solve(nums):
    memo = {}
    def dp(i):
        if i >= len(nums):
            return 0
        if i in memo:
            return memo[i]
        memo[i] = max(dp(i + 1), nums[i] + dp(i + 2))
        return memo[i]
    return dp(0)

