def min_path_sum(grid):
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = grid[0][0]
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            top = dp[i-1][j] if i else float('inf')
            left = dp[i][j-1] if j else float('inf')
            dp[i][j] = grid[i][j] + min(top, left)
    return dp[-1][-1]

def lcs(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return dp[m][n]

def knapsack01(values, weights, cap):
    dp = [0] * (cap + 1)
    for w, v in zip(weights, values):
        for c in range(cap, w - 1, -1):
            dp[c] = max(dp[c], dp[c - w] + v)
    return dp[cap]

def unbounded(values, weights, cap):
    dp = [0] * (cap + 1)
    for c in range(1, cap + 1):
        for w, v in zip(weights, values):
            if w <= c:
                dp[c] = max(dp[c], dp[c - w] + v)
    return dp[cap]

def subset_sum(nums, target):
    dp = [False] * (target + 1)
    dp[0] = True
    for x in nums:
        for c in range(target, x - 1, -1):
            dp[c] = dp[c] or dp[c - x]
    return dp[target]

def count_subsets(nums, target):
    dp = [0] * (target + 1)
    dp[0] = 1
    for x in nums:
        for c in range(target, x - 1, -1):
            dp[c] += dp[c - x]
    return dp[target]

def min_cut(s):
    n = len(s)
    is_pal = [[False] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            is_pal[i][j] = s[i] == s[j] and (j - i < 2 or is_pal[i+1][j-1])
    dp = [float('inf')] * n
    for j in range(n):
        if is_pal[0][j]:
            dp[j] = 0
        else:
            for i in range(j):
                if is_pal[i+1][j]:
                    dp[j] = min(dp[j], dp[i] + 1)
    return dp[-1]

def max_coins(nums):
    nums = [1] + nums + [1]
    n = len(nums)
    dp = [[0] * n for _ in range(n)]
    for length in range(1, n - 1):
        for i in range(1, n - length):
            j = i + length - 1
            for k in range(i, j + 1):
                coins = nums[i-1] * nums[k] * nums[j+1]
                dp[i][j] = max(dp[i][j], coins + dp[i][k-1] + dp[k+1][j])
    return dp[1][n-2]

