import bisect

def lis_fast(nums):
    tails = []
    for x in nums:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

def edit_distance(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j-1], dp[i-1][j], dp[i][j-1])
    return dp[m][n]

def edit_distance_row(a, b):
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i] + [0] * len(b)
        for j, cb in enumerate(b, 1):
            cur[j] = prev[j-1] if ca == cb else 1 + min(prev[j-1], prev[j], cur[j-1])
        prev = cur
    return prev[-1]

def mcm(dims):
    n = len(dims) - 1
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float('inf')
            for k in range(i, j):
                cost = (dp[i][k] + dp[k+1][j]
                        + dims[i] * dims[k+1] * dims[j+1])
                dp[i][j] = min(dp[i][j], cost)
    return dp[0][n-1]

def unique_paths_with_obstacles(grid):
    m, n = len(grid), len(grid[0])
    dp = [0] * n
    dp[0] = 1 if grid[0][0] == 0 else 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[j] = 0
            elif j > 0:
                dp[j] += dp[j-1]
    return dp[-1]

def max_path_sum(grid):
    m, n = len(grid), len(grid[0])
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            best = -float('inf')
            if i:
                best = max(best, grid[i-1][j])
            if j:
                best = max(best, grid[i][j-1])
            grid[i][j] += best
    return grid[-1][-1]

def rob(root):
    def dfs(node):
        if not node:
            return (0, 0)
        l0, l1 = dfs(node.left)
        r0, r1 = dfs(node.right)
        skip = max(l0, l1) + max(r0, r1)
        take = node.val + l0 + r0
        return (skip, take)
    return max(dfs(root))

def is_match(s, p):
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True
    for j in range(1, n + 1):
        if p[j-1] == '*':
            dp[0][j] = dp[0][j-1]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j-1] in (s[i-1], '?'):
                dp[i][j] = dp[i-1][j-1]
            elif p[j-1] == '*':
                dp[i][j] = dp[i-1][j] or dp[i][j-1]
    return dp[m][n]

def palindrome_table(s):
    n = len(s)
    pal = [[False] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            pal[i][j] = s[i] == s[j] and (j - i < 2 or pal[i+1][j-1])
    return pal

def min_assignment(cost):
    n = len(cost)
    size = 1 << n
    dp = [float('inf')] * size
    dp[0] = 0
    for mask in range(size):
        i = bin(mask).count('1')
        for j in range(n):
            if not (mask >> j) & 1:
                dp[mask | (1 << j)] = min(dp[mask | (1 << j)], dp[mask] + cost[i][j])
    return dp[size - 1]

def tsp(g, n):
    size = 1 << n
    dp = [[float('inf')] * n for _ in range(size)]
    dp[1][0] = 0
    for mask in range(size):
        for u in range(n):
            if dp[mask][u] == float('inf'):
                continue
            for v in range(n):
                if not (mask >> v) & 1:
                    dp[mask | (1 << v)][v] = min(dp[mask | (1 << v)][v], dp[mask][u] + g[u][v])
    return min(dp[size - 1])

def count_valid(n):
    s = str(n)
    from functools import lru_cache
    @lru_cache(None)
    def dp(pos, tight, prev):
        if pos == len(s):
            return 1
        limit = int(s[pos]) if tight else 9
        total = 0
        for d in range(limit + 1):
            if prev == -1 or d != prev:
                total += dp(pos + 1, tight and d == limit, d)
        return total
    return dp(0, True, -1)

